import java.util.*;
import java.math.*;
public class BehaviorCheck {
  public static void main(String[] args) throws Exception {
    var stock=new Stock(5);assert !stock.reserve(6);assert stock.available()==5;
    try{stock.reserve(-2);throw new AssertionError();}catch(IllegalArgumentException expected){}
    var pool=java.util.concurrent.Executors.newFixedThreadPool(8);var futures=new ArrayList<java.util.concurrent.Future<Boolean>>();for(int i=0;i<20;i++)futures.add(pool.submit(()->stock.reserve(1)));int ok=0;for(var f:futures)if(f.get())ok++;pool.shutdown();assert ok==5;assert stock.available()==0;
    System.out.println("BehaviorCheck: PASS");
  }
}

